#include "ui.h"

#include "lv_conf.h"
#include "ui_handlers.h"

#include <string.h>

namespace {

// LVGL 9.6 deprecated lv_obj_add_flag()/lv_obj_remove_flag() in favour of one setter per flag; those setters
// do not exist on 9.2. These two wrappers are the whole difference, so one generated file builds on both.
#if LVGL_VERSION_MAJOR > 9 || (LVGL_VERSION_MAJOR == 9 && LVGL_VERSION_MINOR >= 6)
void ui_set_hidden(lv_obj_t *object, bool hidden) {
    lv_obj_set_hidden(object, hidden);
}
void ui_set_scrollable(lv_obj_t *object, bool scrollable) {
    lv_obj_set_scrollable(object, scrollable);
}
#else
void ui_set_hidden(lv_obj_t *object, bool hidden) {
    if (hidden) {
        lv_obj_add_flag(object, LV_OBJ_FLAG_HIDDEN);
    } else {
        lv_obj_remove_flag(object, LV_OBJ_FLAG_HIDDEN);
    }
}
void ui_set_scrollable(lv_obj_t *object, bool scrollable) {
    if (scrollable) {
        lv_obj_add_flag(object, LV_OBJ_FLAG_SCROLLABLE);
    } else {
        lv_obj_remove_flag(object, LV_OBJ_FLAG_SCROLLABLE);
    }
}
#endif

lv_obj_t *view_main = nullptr;

void on_go_clicked_cb(lv_event_t *event) {
    lv_obj_t *target = static_cast<lv_obj_t *>(lv_event_get_target(event));
    (void)target;
    on_go_clicked();
}


} // namespace

void ui_show_view(const char *view_id) {
    if (strcmp(view_id, "main") == 0) {
        ui_set_hidden(view_main, false);
    } else {
        ui_set_hidden(view_main, true);
    }
}

void ui_init() {
    lv_obj_t *screen = lv_screen_active();
    ui_set_scrollable(screen, false);

    view_main = lv_obj_create(screen);
    lv_obj_set_pos(view_main, 0, 0);
    lv_obj_set_size(view_main, 240, 240);
    lv_obj_set_style_border_width(view_main, 0, 0);
    lv_obj_set_style_radius(view_main, 0, 0);
    lv_obj_set_style_bg_opa(view_main, LV_OPA_TRANSP, 0);

    lv_obj_t *w_title = lv_label_create(view_main);
    lv_obj_set_pos(w_title, 16, 8);
    lv_obj_set_size(w_title, 208, 26);
    lv_label_set_long_mode(w_title, LV_LABEL_LONG_WRAP);
    lv_label_set_text(w_title, "Rusty Platform");

    lv_obj_t *w_go = lv_button_create(view_main);
    lv_obj_set_pos(w_go, 50, 100);
    lv_obj_set_size(w_go, 140, 40);
    lv_obj_t *w_go_label = lv_label_create(w_go);
    lv_label_set_text(w_go_label, "Press me");
    lv_obj_center(w_go_label);
    lv_obj_add_event_cb(w_go, on_go_clicked_cb, LV_EVENT_CLICKED, nullptr);

    Serial.printf("ui: 2 widget(s), 1 view(s)\n");
}

void ui_tick() {
    // No clock in this design runs by itself; nothing to recompute here.
}
